package com.TechHurts.CodeFile;
import android.app.*;
import android.content.*;
import android.view.*;
import android.widget.*;
import android.os.Looper;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import org.robolectric.android.controller.ActivityController;
import java.io.*;
import java.util.zip.GZIPInputStream;
import static org.junit.Assert.*;
import static org.robolectric.Shadows.shadowOf;
import io.github.rosemoe.sora.widget.CodeEditor;

@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class NativeActivityTest {
 private <T> T find(View view,Class<T> cls){if(cls.isInstance(view))return cls.cast(view);if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){T found=find(g.getChildAt(i),cls);if(found!=null)return found;}}return null;}
 private Button button(View view,String name){if(view instanceof Button&&name.equals(String.valueOf(view.getContentDescription())))return (Button)view;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++){Button found=button(g.getChildAt(i),name);if(found!=null)return found;}}return null;}
 private void noBrowser(View v){assertFalse(v.getClass().getName().startsWith("android.webkit."));if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)noBrowser(g.getChildAt(i));}}
 @Test public void nativeActivityShowsReadOnlyEditorAndNativeDialogs(){try(ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity activity=controller.get();View root=activity.getWindow().getDecorView();CodeEditor editor=find(root,CodeEditor.class);assertNotNull(editor);assertFalse(editor.isEditable());assertTrue(editor.getText().toString().contains("class Welcome"));noBrowser(root);button(root,"Settings").performClick();AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertTrue(dialog.isShowing());assertNotNull(button(dialog.getWindow().getDecorView(),"Share debug log (.gz)"));noBrowser(dialog.getWindow().getDecorView());dialog.dismiss();}}
 @Test public void sourceFromShareIntentIsNotExecutable(){Intent intent=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,"<script>alert('no')</script>");try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class,intent).setup()){shadowOf(Looper.getMainLooper()).idle();CodeEditor editor=find(c.get().getWindow().getDecorView(),CodeEditor.class);assertEquals("<script>alert('no')</script>",editor.getText().toString());}}
 @Test public void diagnosticsAreActualGzipAndNeverIncludeSource(){Application app=RuntimeEnvironment.getApplication();DebugLog log=new DebugLog(app);log.event("native.test");try{File gz=log.gzip(app);String text;try(GZIPInputStream in=new GZIPInputStream(new FileInputStream(gz))){text=new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}assertTrue(text.contains("native.test"));assertTrue(text.contains("UI: native Android"));assertFalse(text.contains("<script>"));}catch(Exception e){throw new AssertionError(e);}}
 @Test public void bundledGrammarsLoadIntoNativeEditor() throws Exception {NativeSyntax syntax=new NativeSyntax();syntax.load(RuntimeEnvironment.getApplication());assertTrue(syntax.names().size()>=66);CodeEditor editor=new CodeEditor(RuntimeEnvironment.getApplication());try{for(String name:new String[]{"a.java","a.ts","a.py","a.rs","a.kt","a.cpp","a.yaml"}){String lang=syntax.detect(name);assertNotEquals("plain",lang);syntax.apply(editor,lang,"darcula");assertTrue(editor.getEditorLanguage().getClass().getName().contains("TextMate"));}for(String language:syntax.names())if(!language.equals("plain"))syntax.apply(editor,language,"darcula");}finally{editor.release();}}
 @Test public void workspaceReflowsAcrossPhoneTabletAndSeparatingHinge() throws Exception {
  try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){
   MainActivity a=c.get();java.lang.reflect.Field field=MainActivity.class.getDeclaredField("workspace");field.setAccessible(true);ViewGroup workspace=(ViewGroup)field.get(a);CodeEditor editor=find(a.getWindow().getDecorView(),CodeEditor.class);String source=editor.getText().toString();
   int w=a.dp(1200),h=a.dp(800);workspace.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));workspace.layout(0,0,w,h);assertEquals(a.dp(300),workspace.getChildAt(1).getLeft());
   w=a.dp(400);workspace.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));workspace.layout(0,0,w,h);assertEquals(0,workspace.getChildAt(1).getLeft());assertTrue(workspace.getChildAt(1).getTop()>0);assertSame(editor,find(workspace,CodeEditor.class));assertEquals(source,editor.getText().toString());assertTrue(editor.isScalable());assertTrue(editor.isWordwrap());
   java.lang.reflect.Field hinge=workspace.getClass().getDeclaredField("hinge");hinge.setAccessible(true);int[] origin=new int[2];workspace.getLocationInWindow(origin);hinge.set(workspace,new android.graphics.Rect(origin[0]+a.dp(490),origin[1],origin[0]+a.dp(510),origin[1]+h));w=a.dp(1000);workspace.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));workspace.layout(0,0,w,h);assertEquals(a.dp(510),workspace.getChildAt(1).getLeft());
   hinge.set(workspace,new android.graphics.Rect(origin[0],origin[1]+a.dp(300),origin[0]+w,origin[1]+a.dp(320)));workspace.requestLayout();workspace.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));workspace.layout(0,0,w,h);assertEquals(a.dp(320),workspace.getChildAt(1).getTop());
  }
 }
 @Test public void nativeZoomAndFitWidthDoNotChangeSource(){try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){View root=c.get().getWindow().getDecorView();CodeEditor editor=find(root,CodeEditor.class);String text=editor.getText().toString();float size=editor.getTextSizePx();button(root,"Zoom +").performClick();assertTrue(editor.getTextSizePx()>size);button(root,"Wrap").performClick();assertFalse(editor.isWordwrap());button(root,"Fit width").performClick();assertTrue(editor.isWordwrap());assertEquals(text,editor.getText().toString());}}
 private void touch(CodeEditor editor,long start,long time,int action,float x1,float y1,Float x2,Float y2){int count=x2==null?1:2;MotionEvent.PointerProperties[] props=new MotionEvent.PointerProperties[count];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[count];for(int i=0;i<count;i++){props[i]=new MotionEvent.PointerProperties();props[i].id=i;props[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=i==0?x1:x2;coords[i].y=i==0?y1:y2;coords[i].pressure=1;coords[i].size=1;}MotionEvent event=MotionEvent.obtain(start,time,action,count,props,coords,0,0,1,1,0,0,android.view.InputDevice.SOURCE_TOUCHSCREEN,0);editor.dispatchTouchEvent(event);event.recycle();}
 @Test public void nativeTouchPinchZoomChangesScaleWithoutEditing(){try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){CodeEditor editor=find(c.get().getWindow().getDecorView(),CodeEditor.class);editor.measure(View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));editor.layout(0,0,800,600);String text=editor.getText().toString();float oldSize=editor.getTextSizePx();long t=android.os.SystemClock.uptimeMillis();touch(editor,t,t,MotionEvent.ACTION_DOWN,250,250,null,null);touch(editor,t,t+30,MotionEvent.ACTION_POINTER_DOWN|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),250,250,450f,250f);for(int i=1;i<=8;i++)touch(editor,t,t+30+i*30,MotionEvent.ACTION_MOVE,250-i*12,250,450f+i*12,250f);touch(editor,t,t+300,MotionEvent.ACTION_POINTER_UP|(1<<MotionEvent.ACTION_POINTER_INDEX_SHIFT),154,250,546f,250f);touch(editor,t,t+320,MotionEvent.ACTION_UP,154,250,null,null);assertTrue("Native pinch should zoom",editor.getTextSizePx()>oldSize);assertEquals(text,editor.getText().toString());}}
 @Test @org.robolectric.annotation.GraphicsMode(org.robolectric.annotation.GraphicsMode.Mode.NATIVE)
 public void nativePortraitRendersToBitmap() throws Exception {try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).setup()){MainActivity a=c.get();View root=a.getWindow().getDecorView();int width=480,height=1000;root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));root.layout(0,0,width,height);CodeEditor renderedEditor=find(root,CodeEditor.class);java.lang.reflect.Field ready=MainActivity.class.getDeclaredField("syntaxReady");ready.setAccessible(true);for(int attempt=0;attempt<100;attempt++){shadowOf(Looper.getMainLooper()).idle();root.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));root.layout(0,0,width,height);if(ready.getBoolean(a)&&renderedEditor.getLayout().getRowCount()>renderedEditor.getText().getLineCount())break;Thread.sleep(50);}assertTrue("Grammars initialized",ready.getBoolean(a));assertTrue("Long source lines visibly reflow into multiple display rows",renderedEditor.getLayout().getRowCount()>renderedEditor.getText().getLineCount());for(int frame=0;frame<20;frame++){Thread.sleep(50);shadowOf(Looper.getMainLooper()).idle();}android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(width,height,android.graphics.Bitmap.Config.ARGB_8888);root.draw(new android.graphics.Canvas(bitmap));File out=new File("build/native-portrait.png");out.getParentFile().mkdirs();try(FileOutputStream stream=new FileOutputStream(out)){assertTrue(bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,stream));}assertTrue(find(root,CodeEditor.class).getHeight()>200);}}
}
